@startuml

class OilWell {
  + code : string
  + pollutionRate() : float
}

abstract class WellCategory {}

class OnshoreWell {
  + surfaceExtension : float
}

class OffshoreWell {
  + installationYear : int
}

class OilCompany {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class ExtractionInfo {
  + quantity : float
}

WellCategory <|-- OnshoreWell
WellCategory <|-- OffshoreWell

OilWell --|> WellCategory

OilWell "1" o-- "0..*" ExtractionInfo
OilCompany "1" o-- "0..*" ExtractionInfo
ExtractionInfo -- OilWell
ExtractionInfo -- OilCompany

OffshoreWell "0..1" o-- "0..1" GeographicalArea

@enduml

